import { defineComponentSlotStyle } from "@yamada-ui/react"

export const marqueeStyle = defineComponentSlotStyle({
  base: {
    content: {
      "&:not([data-ready])": { animationName: "none" },
      alignItems: "center",
      animationDelay: "{delay}",
      animationDirection: "{direction}",
      animationDuration: "{duration}",
      animationFillMode: "both",
      animationIterationCount: "{loop-count}",
      animationPlayState: "{play-state}",
      animationTimingFunction: "linear",
      display: "flex",
      flex: "0 0 auto",
      minW: "0",
      position: "relative",
      _horizontal: { w: "max-content" },
      _keyframes: {
        to: {
          transform: "translate({translate-x}, {translate-y})",
        },
      },
      _mediaReduceMotion: { animationName: "none" },
      _vertical: { flexDirection: "column", h: "max-content" },
    },
    edge: {
      pointerEvents: "none",
      position: "absolute",
      zIndex: "1",
      _horizontal: {
        bottom: "0",
        top: "0",
        w: "{edge-size}",
        _end: {
          bgGradient: "linear(to-l, {edge-color}, transparent)",
          insetInlineEnd: "0",
          _rtl: {
            bgGradient: "linear(to-r, {edge-color}, transparent)",
          },
        },
        _start: {
          bgGradient: "linear(to-r, {edge-color}, transparent)",
          insetInlineStart: "0",
          _rtl: {
            bgGradient: "linear(to-l, {edge-color}, transparent)",
          },
        },
      },
      _vertical: {
        h: "{edge-size}",
        insetInline: "0",
        _end: {
          bgGradient: "linear(to-t, {edge-color}, transparent)",
          bottom: "0",
        },
        _start: {
          bgGradient: "linear(to-b, {edge-color}, transparent)",
          top: "0",
        },
      },
    },
    group: {
      "&[data-clone]": {
        display: "{clone-display, flex}",
        position: "absolute",
        _horizontal: {
          transform: "translateX(calc({copy-offset-x} * {index}))",
          w: "max-content",
        },
        _vertical: {
          transform: "translateY(calc({distance} * {index}))",
          w: "full",
        },
      },
      alignItems: "center",
      display: "flex",
      flex: "0 0 auto",
      gap: "{gap}",
      _horizontal: { pe: "{gap}" },
      _mediaReduceMotion: { "&[data-clone]": { display: "none" } },
      _vertical: { flexDirection: "column", pb: "{gap}" },
    },
    item: { flexShrink: 0 },
    root: {
      "&[data-pause-on-focus]": {
        _nativeFocusWithin: {
          "& > [data-marquee-content]": { transform: "none !important" },
          "--clone-display": "none",
          "--play-state": "paused",
          overflow: "auto",
        },
      },
      "&[data-pause-on-hover]": {
        _hover: { "--play-state": "paused" },
      },
      "--copy-offset-x": "{distance}",
      "--edge-color": "colors.bg",
      "--edge-size": "20%",
      "--gap": "spaces.4",
      "--play-state": "running",
      "--translate-x": "calc({distance} * -1)",
      "--translate-y": "0px",
      overflow: "hidden",
      position: "relative",
      rounded: "l2",
      w: "full",
      _complete: {
        "& > [data-marquee-content]": { transform: "none !important" },
        "--clone-display": "none",
        overflow: "auto",
      },
      _horizontal: {
        "&[dir=rtl]": {
          "--copy-offset-x": "calc({distance} * -1)",
          "--translate-x": "{distance}",
        },
      },
      _mediaReduceMotion: { overflow: "auto" },
      _paused: { "--play-state": "paused" },
      _vertical: {
        "--translate-x": "0px",
        "--translate-y": "calc({distance} * -1)",
      },
    },
  },
})

export type MarqueeStyle = typeof marqueeStyle

"use client"

import type { CSSProps,
  HTMLStyledProps,
  SimpleDirection,
  ThemeProps, Merge } from "@yamada-ui/react"
import type { MarqueeStyle } from "./marquee.style"
import type { UseMarqueeProps } from "./use-marquee"
import { useMemo } from "react"
import { createSlotComponent, styled, varAttr, useFindChild,
  useOmitChildren,
  usePickChildren,
  useValidChildren, } from "@yamada-ui/react"
import { marqueeStyle } from "./marquee.style"
import { MarqueeContext, useMarquee, useMarqueeContext } from "./use-marquee"

export interface MarqueeRootProps
  extends Merge<HTMLStyledProps, UseMarqueeProps>, ThemeProps<MarqueeStyle> {
  /**
   * The color of the edge gradient.
   *
   * @default 'bg'
   */
  edgeColor?: CSSProps["color"]
  /**
   * The size of the edge gradient.
   *
   * @default '20%'
   */
  edgeSize?: CSSProps["width"]
  /**
   * Props for content component.
   */
  contentProps?: MarqueeContentProps
}

const {
  PropsContext: MarqueePropsContext,
  usePropsContext: useMarqueePropsContext,
  withContext,
  withProvider,
} = createSlotComponent<MarqueeRootProps, MarqueeStyle>("marquee", marqueeStyle)

export { MarqueePropsContext, useMarqueePropsContext }

/**
 * `Marquee` continuously scrolls content horizontally or vertically.
 *
 * @see https://yamada-ui.com/docs/components/marquee
 */
export const MarqueeRoot = withProvider<"div", MarqueeRootProps>(
  ({ children, contentProps, ...rest }) => {
    const validChildren = useValidChildren(children)
    const customContent = useFindChild(validChildren, MarqueeContent)
    const items = usePickChildren(validChildren, MarqueeItem)
    const otherChildren = useOmitChildren(validChildren, MarqueeItem)
    const {
      copies,
      getContentProps,
      getEdgeProps,
      getGroupProps,
      getRootProps,
    } = useMarquee(rest)
    const context = useMemo(
      () => ({ copies, getContentProps, getEdgeProps, getGroupProps }),
      [copies, getContentProps, getEdgeProps, getGroupProps],
    )

    return (
      <MarqueeContext value={context}>
        <styled.div {...getRootProps()}>
          {customContent ? (
            children
          ) : (
            <>
              <MarqueeContent {...contentProps}>{items}</MarqueeContent>
              {otherChildren}
            </>
          )}
        </styled.div>
      </MarqueeContext>
    )
  },
  "root",
)(undefined, ({ edgeColor, edgeSize, gap, ...rest }) => ({
  ...rest,
  "--edge-color": varAttr(edgeColor, "colors"),
  "--edge-size": varAttr(edgeSize, "sizes"),
  "--gap": varAttr(gap, "spaces"),
}))

export interface MarqueeContentProps extends HTMLStyledProps {}

export const MarqueeContent = withContext<"div", MarqueeContentProps>(
  ({ children, ...rest }) => {
    const { copies, getContentProps, getGroupProps } = useMarqueeContext()

    return (
      <styled.div {...getContentProps(rest)}>
        {Array.from({ length: copies + 1 }, (_, index) => (
          <MarqueeGroup key={index} {...getGroupProps({ index })}>
            {children}
          </MarqueeGroup>
        ))}
      </styled.div>
    )
  },
  "content",
)()

const MarqueeGroup = withContext("div", "group")()

export interface MarqueeItemProps extends HTMLStyledProps {}

export const MarqueeItem = withContext<"div", MarqueeItemProps>("div", "item")()

export interface MarqueeEdgeProps extends Omit<HTMLStyledProps, "direction"> {
  /**
   * The edge to fade, relative to the marquee orientation.
   *
   * @default 'start'
   */
  direction?: SimpleDirection
}

export const MarqueeEdge = withContext<"div", MarqueeEdgeProps>("div", "edge")(
  undefined,
  (props) => {
    const { getEdgeProps } = useMarqueeContext()

    return getEdgeProps(props)
  },
)

"use client"

import type {
  AnimationEvent,
  FocusEvent,
  KeyboardEvent,
  RefObject,
} from "react"
import type {
  HTMLProps,
  Orientation,
  PropGetter,
  SimpleDirection,
} from "@yamada-ui/react"
import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import {
  mergeProps,
  assignRef,
  createContext,
  dataAttr,
  mergeRefs,
  useCallbackRef,
} from "@yamada-ui/react"
import { useControllableState } from "../../hooks/use-controllable-state"
import { useI18n } from "../../providers/i18n-provider"

export interface MarqueeControl {
  /**
   * Whether the marquee is paused.
   */
  paused: boolean
  /**
   * Pauses the marquee.
   */
  pause: () => void
  /**
   * Restarts the animation, including its delay and loop count.
   */
  restart: () => void
  /**
   * Resumes the marquee.
   */
  resume: () => void
  /**
   * Toggles the pause state.
   */
  togglePause: () => void
}

export interface UseMarqueeProps extends HTMLProps {
  /**
   * Ref of the marquee controls.
   */
  controlRef?: RefObject<MarqueeControl | null>
  /**
   * Whether the marquee is initially paused.
   *
   * @default false
   */
  defaultPaused?: boolean
  /**
   * The delay before the animation starts, in seconds.
   *
   * @default 0
   */
  delay?: number
  /**
   * The direction the content scrolls towards.
   *
   * @default 'start'
   */
  direction?: SimpleDirection
  /**
   * The duration of one loop in seconds. Overrides `speed`.
   */
  duration?: number
  /**
   * The number of animation loops. Set to `0` for infinite loops.
   *
   * @default 0
   */
  loopCount?: number
  /**
   * The orientation of the marquee.
   *
   * @default 'horizontal'
   */
  orientation?: Orientation
  /**
   * If `true`, the animation is paused.
   *
   * @default false
   */
  paused?: boolean
  /**
   * If `true`, the animation pauses while an item is focused.
   *
   * @default false
   */
  pauseOnFocus?: boolean
  /**
   * If `true`, the animation pauses on hover.
   *
   * @default false
   */
  pauseOnHover?: boolean
  /**
   * If `true`, the scrolling direction is reversed.
   *
   * @default false
   */
  reverse?: boolean
  /**
   * The scrolling speed in pixels per second.
   *
   * @default 50
   */
  speed?: number
  /**
   * The callback invoked when all finite loops finish.
   */
  onComplete?: () => void
  /**
   * The callback invoked after each animation iteration, except the final one.
   */
  onLoopComplete?: () => void
  /**
   * The callback invoked when the persistent pause state changes.
   */
  onPauseChange?: (paused: boolean) => void
}

interface MarqueeContext extends Pick<
  UseMarqueeReturn,
  "copies" | "getContentProps" | "getEdgeProps" | "getGroupProps"
> {}

const [MarqueeContext, useMarqueeContext] = createContext<MarqueeContext>({
  name: "MarqueeContext",
})

export { MarqueeContext, useMarqueeContext }

export function useMarquee({
  controlRef,
  defaultPaused = false,
  delay = 0,
  dir: dirProp,
  direction = "start",
  duration: durationProp,
  loopCount = 0,
  orientation = "horizontal",
  paused: pausedProp,
  pauseOnFocus = false,
  pauseOnHover = false,
  reverse = false,
  speed = 50,
  onComplete: onCompleteProp,
  onLoopComplete: onLoopCompleteProp,
  onPauseChange,
  ...rest
}: UseMarqueeProps = {}) {
  const { dir: defaultDir } = useI18n()
  const dir = dirProp ?? defaultDir
  const vertical = orientation === "vertical"
  const rootRef = useRef<HTMLDivElement>(null)
  const contentRef = useRef<HTMLDivElement>(null)
  const trackRef = useRef<HTMLDivElement>(null)
  const [hovered, setHovered] = useState(false)
  const [focused, setFocused] = useState(false)
  const [completed, setCompleted] = useState(false)
  const [paused, setPaused] = useControllableState({
    defaultValue: defaultPaused,
    value: pausedProp,
    onChange: onPauseChange,
  })
  const onComplete = useCallbackRef(onCompleteProp)
  const onLoopComplete = useCallbackRef(onLoopCompleteProp)
  const [size, setSize] = useState({ content: 0, root: 0 })
  const duration = durationProp ?? (speed > 0 ? size.content / speed : 0)
  const ready = size.content > 0 && Number.isFinite(duration) && duration > 0
  const copies = Math.max(
    1,
    size.content > 0 ? Math.ceil(size.root / size.content) : 1,
  )
  const iterations = Number.isFinite(loopCount) && loopCount > 0 ? loopCount : 0
  const animationDirection =
    (direction === "end") !== reverse ? "reverse" : "normal"
  const interactionPaused =
    (pauseOnHover && hovered) || (pauseOnFocus && focused)
  const animationPaused = paused || interactionPaused || completed || !ready

  const pause = useCallback(() => setPaused(true), [setPaused])
  const resume = useCallback(() => setPaused(false), [setPaused])
  const togglePause = useCallback(() => setPaused((prev) => !prev), [setPaused])
  const restart = useCallback(() => {
    trackRef.current?.getAnimations().forEach((animation) => {
      animation.currentTime = 0
    })
    setCompleted(false)
  }, [])
  const control = useMemo<MarqueeControl>(
    () => ({ pause, paused: animationPaused, restart, resume, togglePause }),
    [animationPaused, pause, restart, resume, togglePause],
  )

  assignRef(controlRef, control)

  useEffect(() => {
    const root = rootRef.current
    const content = contentRef.current

    if (!root || !content) return

    const observer = new ResizeObserver((entries) => {
      entries.forEach(({ target, borderBoxSize }) => {
        const box = borderBoxSize[0]

        if (!box) return

        const key = target === root ? "root" : "content"
        const value = vertical ? box.blockSize : box.inlineSize

        setSize((prev) =>
          prev[key] === value ? prev : { ...prev, [key]: value },
        )
      })
    })

    observer.observe(root, { box: "border-box" })
    observer.observe(content, { box: "border-box" })

    return () => observer.disconnect()
  }, [vertical])

  const getRootProps: PropGetter = useCallback(
    (props = {}) =>
      mergeProps(
        {
          style: {
            "--delay": `${Number.isFinite(delay) ? delay : 0}s`,
            "--direction": animationDirection,
            "--distance": `${size.content}px`,
            "--duration": `${ready ? duration : 0}s`,
            "--loop-count": iterations || "infinite",
          },
          "aria-keyshortcuts": "Space",
          "aria-live": "off",
          "aria-roledescription": "marquee",
          role: "region",
          tabIndex: 0,
        },
        rest,
        props,
        {
          ref: rootRef,
          "data-complete": dataAttr(completed),
          "data-end": dataAttr(direction === "end"),
          "data-orientation": orientation,
          "data-pause-on-focus": dataAttr(pauseOnFocus),
          "data-pause-on-hover": dataAttr(pauseOnHover),
          "data-paused": dataAttr(animationPaused),
          "data-start": dataAttr(direction === "start"),
          dir,
          onBlurCapture: (ev: FocusEvent<HTMLDivElement>) => {
            if (ev.currentTarget.contains(ev.relatedTarget)) return

            setFocused(false)

            if (!pauseOnFocus) return

            ev.currentTarget.scrollLeft = 0
            ev.currentTarget.scrollTop = 0
          },
          onFocusCapture: () => setFocused(true),
          onKeyDown: (ev: KeyboardEvent<HTMLDivElement>) => {
            if (
              ev.target !== ev.currentTarget ||
              ev.key !== " " ||
              ev.altKey ||
              ev.ctrlKey ||
              ev.metaKey ||
              ev.repeat
            )
              return

            ev.preventDefault()
            togglePause()
          },
          onMouseEnter: () => setHovered(true),
          onMouseLeave: () => setHovered(false),
        },
      )(),
    [
      rest,
      direction,
      orientation,
      pauseOnFocus,
      pauseOnHover,
      animationPaused,
      completed,
      ready,
      dir,
      duration,
      animationDirection,
      delay,
      iterations,
      size.content,
      togglePause,
    ],
  )

  const getContentProps: PropGetter = useCallback(
    (props = {}) =>
      mergeProps(props, {
        ref: trackRef,
        "data-marquee-content": "",
        "data-orientation": orientation,
        "data-ready": dataAttr(ready),
        onAnimationEnd: (ev: AnimationEvent<HTMLDivElement>) => {
          if (ev.target !== ev.currentTarget || !iterations) return

          setCompleted(true)
          onComplete()
        },
        onAnimationIteration: (ev: AnimationEvent<HTMLDivElement>) => {
          if (ev.target === ev.currentTarget) onLoopComplete()
        },
      })(),
    [orientation, ready, iterations, onComplete, onLoopComplete],
  )

  const getEdgeProps: PropGetter<"div", { direction?: SimpleDirection }> =
    useCallback(
      ({ direction = "start", ...props } = {}) =>
        mergeProps(props, {
          "aria-hidden": true,
          "data-end": dataAttr(direction === "end"),
          "data-orientation": orientation,
          "data-start": dataAttr(direction === "start"),
          dir,
          inert: true,
        })(),
      [dir, orientation],
    )

  const getGroupProps: PropGetter<"div", { index?: number }> = useCallback(
    ({ id, ref, index = 0, ...props } = {}) =>
      mergeProps({ style: { "--index": index } }, props, {
        id: index ? undefined : id,
        ref: index ? undefined : mergeRefs(ref, contentRef),
        "aria-hidden": index ? true : undefined,
        "data-clone": dataAttr(!!index),
        "data-orientation": orientation,
        inert: index ? true : undefined,
      })(),
    [orientation],
  )

  return {
    control,
    copies,
    getContentProps,
    getEdgeProps,
    getGroupProps,
    getRootProps,
  }
}

export type UseMarqueeReturn = ReturnType<typeof useMarquee>
